mapper.select:
SELECT message_id AS messageId,turn_id AS turnId,ordinal,role,blocks_json AS blocksJson,created_at AS createdAt
FROM messages WHERE thread_id=#{threadId} AND ordinal>=#{retainedFromOrdinal}
ORDER BY ordinal LIMIT #{limit}

SELECT activity_sequence AS activitySequence,activity_id AS activityId,root_thread_id AS rootThreadId,
  task_thread_id AS taskThreadId,actor_thread_id AS actorThreadId,causal_turn_id AS causalTurnId,
  kind,summary_json AS summaryJson,created_at AS createdAt
FROM task_activities WHERE task_thread_id=#{taskThreadId} AND activity_sequence>#{afterSequence}
ORDER BY activity_sequence LIMIT #{limit}

mapper.update:
UPDATE task_mailbox SET state='BOUND',bound_turn_id=#{turnId},updated_at=#{occurredAt}
WHERE mailbox_sequence IN (
  SELECT mailbox_sequence FROM task_mailbox
  WHERE target_thread_id=#{targetThreadId} AND state='PENDING'
  ORDER BY mailbox_sequence LIMIT #{limit}
)

UPDATE task_projections SET revision=revision+1,state=#{state},latest_activity_sequence=#{latestActivitySequence},
  unread_count=unread_count+CASE WHEN #{incrementUnread} THEN 1 ELSE 0 END,
  latest_safe_summary=#{latestSafeSummary},
  started_at=COALESCE(started_at,#{startedAt}),completed_at=#{completedAt},updated_at=#{occurredAt}
WHERE task_thread_id=#{taskThreadId} AND revision=#{expectedRevision}
  AND state NOT IN ('COMPLETED','FAILED','CANCELLED')

UPDATE task_projections SET revision=revision+1,state=#{state},latest_activity_sequence=#{latestActivitySequence},
  unread_count=unread_count+CASE WHEN #{incrementUnread} THEN 1 ELSE 0 END,
  latest_safe_summary=#{latestSafeSummary},
  started_at=COALESCE(started_at,#{startedAt}),completed_at=#{completedAt},updated_at=#{occurredAt}
WHERE task_thread_id=#{taskThreadId} AND revision=#{expectedRevision}

UPDATE task_projections SET revision=revision+1,latest_activity_sequence=#{latestActivitySequence},
  unread_count=unread_count+1,latest_safe_summary=#{latestSafeSummary},updated_at=#{occurredAt}
WHERE task_thread_id=#{taskThreadId} AND revision=#{expectedRevision}

UPDATE task_projections AS p SET descendant_count=(
  WITH RECURSIVE descendants(thread_id) AS (
    SELECT child_thread_id FROM thread_lineage WHERE parent_thread_id=p.task_thread_id AND lifecycle='ATTACHED'
    UNION ALL
    SELECT l.child_thread_id FROM thread_lineage l JOIN descendants d ON l.parent_thread_id=d.thread_id WHERE l.lifecycle='ATTACHED'
  ) SELECT COUNT(*) FROM descendants
),running_descendant_count=(
  WITH RECURSIVE descendants(thread_id) AS (
    SELECT child_thread_id FROM thread_lineage WHERE parent_thread_id=p.task_thread_id AND lifecycle='ATTACHED'
    UNION ALL SELECT l.child_thread_id FROM thread_lineage l JOIN descendants d ON l.parent_thread_id=d.thread_id WHERE l.lifecycle='ATTACHED'
  ) SELECT COUNT(*) FROM task_projections WHERE task_thread_id IN (SELECT thread_id FROM descendants)
    AND state='RUNNING'
),needs_attention_count=(
  WITH RECURSIVE descendants(thread_id) AS (
    SELECT child_thread_id FROM thread_lineage WHERE parent_thread_id=p.task_thread_id AND lifecycle='ATTACHED'
    UNION ALL SELECT l.child_thread_id FROM thread_lineage l JOIN descendants d ON l.parent_thread_id=d.thread_id WHERE l.lifecycle='ATTACHED'
  ) SELECT COUNT(*) FROM task_projections WHERE task_thread_id IN (SELECT thread_id FROM descendants)
    AND state IN ('WAITING_APPROVAL','SUSPENDED')
),revision=revision+1,updated_at=#{occurredAt}
WHERE p.root_thread_id=#{rootThreadId}
